\label{thm:main_isotopy_regularity}
Let $h: M \to \mathbb{R}$ be a smooth function, and let $c := \sup_M |h|$. Let $U \subset M$ be a sufficiently small (see \S\ref{sec:MSYintreg} for a precise definition) open set with $C^1$ boundary, and let $\Omega_0 \subset M$ be an open subset with smooth boundary having tranverse intersection with $\partial U$. Let $\{\phi_k\}_{k\in\mathbb{N}} \subset \mathcal{I}(U)$, $\Omega_k := \phi_k(1, \Omega_0)$, and $\Sigma_k := \partial \Omega_k \cap U$ be a sequence satisfying
\begin{equation}\label{eqn:main_isotopy_problem}
    \mathcal{A}^h(\Omega_k) \leq \inf_{\phi \in \mathcal{I}(U)} \mathcal{A}^h(\phi(1, \Omega_0)) + \varepsilon_k
\end{equation}
for $\varepsilon_k \to 0$. Then there is a varifold $V$, an open set $\Omega \subset U$, and a subsequence (not relabeled) so that
\[ \mathbf{1}_{\Omega_k \cap U} \xrightarrow{L^1} \mathbf{1}_{\Omega},\ \ D\mathbf{1}_{\Omega_k \cap U} \overset{\ast}{\rightharpoonup} D\mathbf{1}_{\Omega},\ \ \mathbf{v}(\Sigma_k) \rightharpoonup V. \]
$V$ is an integer rectifiable varifold with $c$-bounded first variation. For every $x \in \mathrm{spt}\|V\|$, we have $\Theta^2(\|V\|, x) = n_x \in \mathbb{N}$. If $h(x) \neq 0$, then $n_x \in \{1\} \cup 2\mathbb{N}$. For every $x \in \mathrm{spt}\|V\|$, there is a neighborhood $W_x$ of $x$ so that the following hold.
\begin{itemize}
    \item $V \llcorner G(W_x,2) = \sum_{l=1}^{n_x}\mathbf{v}(N_l, 1)$, where $N_l \subset W_x$ is a $C^{1,1}$ surface with $c$-bounded first variation. Moreover, each $N_l$ is on one side of $N_{l'}$ intersecting tangentially at $x$ for any $l,\ l' \in \{1, \hdots, n_x\}$.
    \item If $n_x = 1$, then
    \begin{itemize}
        \item $\|V\| \llcorner W_x = |D\mathbf{1}_{\Omega}| \llcorner W_x$,
        \item $V \llcorner G(W_x,2) = \mathbf{v}(N, 1)$, where $N \subset W_x$ is a smooth stable surface with prescribed mean curvature $h$ with respect to the set $\Omega \cap W_x$.
    \end{itemize}
    \item If $h(x) \neq 0$ and $n_y = 2n$ for all $y \in \mathrm{spt}\|V\| \cap W_x'$ for an open set $W_x' \subset W_x$ containing $x$, then $V \llcorner G(W'_x,2) = \mathbf{v}(N, 2n)$, where $N\subset W_x'$ is a smooth stable minimal surface. Moreover, $\Omega \cap W_x' = W_x' \setminus N$ if $h(x) > 0$, and $\Omega \cap W_x' = \varnothing$ if $h(x) < 0$.
    \item If $h(x) \neq 0$, $n_x = 2n$, and there is a sequence $x_j \to x$ with $x_j \in \mathrm{spt}\|V\|$ and $n_{x_j} \neq 2n$, then $n = 1$ and the surfaces $N_1,\ N_2 \subset W_x$ additionally satisfy that the generalized mean curvature of $N_1$ points towards $N_2$ and vice versa. Moreover, the set $\Gamma=\partial(N_1 \cap N_2) \cap W_x$ is locally contained in a $C^{1,\alpha}$ curve and satisfies $\mathcal{H}^1(\Gamma)<+\infty$.
\end{itemize}
Suppose additionally that $U$ is a sufficiently small geodesic ball. Then there is a neighborhood $Y$ of $\partial U$ with $V \llcorner G(Y, 2) = \mathbf{v}(N, 1)$, where $N \subset Y$ is a smooth stable surface of prescribed mean curvature $h$ with respect to $\Omega$ satisfying $\partial N = \partial \Sigma$.

\label{thm:PMC_in_sphere}
There is an open dense set $\mathfrak{P} \subset \{h \in C^{\infty}(S^3) \mid |h| \leq 0.547\}$ so that there is an embedded sphere with prescribed mean curvature $h$ with respect to the round metric for any $h \in \mathfrak{P}$. 
In particular, $\{h \in C^{\infty}(S^3) \mid 0 < h \leq 0.547\} \subset \mathfrak{P}$.

Any minimizer for the problem
\begin{equation}\label{eqn:min_problem}
    \inf_{\phi \in \mathcal{I}(U)} \mathcal{A}^c(\phi(1, \Omega_1 \cup \Omega_2))
\end{equation} 
is graphical, symmetric under vertical reflection, and rotationally symmetric.

\label{lem:thin_isoperimetric_MSY}
There is a constant $\delta \in (0, 1)$ independent of $M$ and $g$ so that if $\Sigma$ is a smooth embedded surface in $M$ and satisfies
\begin{equation}\label{eqn:isoperimetric_smallness_assumption}
    \mathcal{H}^2(\Sigma \cap B_1(x)) < \delta^2
\end{equation}
for all $x \in M$, then there is a unique compact $K_{\Sigma} \subset M$ with $\partial K_{\Sigma} = \Sigma$ and
\begin{equation}\label{eqn:thin_isoperimetric_smallness_conclusion}
    \mathcal{H}^3(K_{\Sigma} \cap B_1(x)) \leq \delta^3
\end{equation}
for all $x\in M$, and
\begin{equation}\label{eqn:thin_isoperimetric_MSY}
    \mathcal{H}^3(K_{\Sigma}) \leq c_1\mathcal{H}^2(\Sigma)^{3/2},
\end{equation}
where $c_1 = c_1(\mu)$. Moreover, if $\Sigma$ is diffeomorphic to $S^2$, then $K_{\Sigma}$ is diffeomorphic to $\overline{\mathbb{B}}$.\footnote{The exponent of $\delta$ in (\ref{eqn:thin_isoperimetric_smallness_conclusion}) is written as 2 in the statement of \cite[Lemma 1]{MSY}, but a quick examination of the proof reveals that it should be 3.}

\label{lem:area_comparison}
Let $U \subset B_{1/2}(x_0)$ and $\theta \in (0, 1/2)$ satisfy
\begin{itemize}
    \item $x_0 \in U$,
    \item $\overline{U}$ is diffeomorphic to $\overline{\mathbb{B}}$,
    \item $d_U$ is convex on $U(\theta)\setminus \overline{U}$,
    \item $\Delta d_U \geq c$ on $U(\theta)\setminus \overline{U}$.
\end{itemize}
Let $\beta \geq 1$ be a constant so that, for each $s \in (\theta /2, \theta)$,
\begin{equation}\label{eqn:area_comparison_isoperimetric_assumption}
    \min\{\mathcal{H}^2(E),\ \mathcal{H}^2(\partial U(s) \setminus E)\} \leq \beta(\mathcal{H}^1(\partial E))^2
\end{equation}
whenever $E$ is a surface in $\partial U(s)$. Let
\begin{equation}\label{eqn:area_comparison_delta_assumption}
    \delta_1 = \min\left\{\delta,\ \frac{\theta}{(1+128c_1)\beta^{1/2}},\ \frac{\theta}{9\beta^{1/2}(1/32 + cc_1)^{1/2}},\ \frac{\mathcal{H}^3(M)^{1/3}}{(4c_1)^{1/3}},\ 1\right\},
\end{equation}
(where $c_1$ and $\delta$ are as in Lemma \ref{lem:thin_isoperimetric_MSY}). Let $\Sigma$ be a smooth embedded disk intersecting $\partial U$ transversally with $\partial \Sigma \subset M \setminus U$. Suppose
\begin{equation}\label{eqn:area_comparison_smallness_assumption}
    \mathcal{H}^2(\partial U) + \mathcal{H}^2(\Sigma\setminus U) \leq \delta_1^2/32.
\end{equation}

If $\Lambda$ is any component of $\Sigma \setminus U$ with $\partial \Sigma \cap \Lambda = \varnothing$, then there is a unique compact $K_{\Lambda} \subset M \setminus U$ so that
\begin{equation}\label{eqn:area_comparison_smallness_conclusion}
    \mathcal{H}^3(K_{\Lambda}) \leq c_1\delta_1^3,\ \ \partial K_{\Lambda} = \Lambda \cup F,
\end{equation}
where $F \subset \partial U$ is a surface with $\partial F = \partial \Lambda$ satisfying
\begin{equation}\label{eqn:area_comparison}
    \mathcal{H}^2(F) < \mathcal{H}^2(\Lambda \cap U(\theta)) - c\mathcal{H}^3(K_{\Lambda}).
\end{equation}

\label{prop:fill-in}
Let $\Sigma \in \mathcal{D}^*(U)$ and $\Sigma_1,\ \Sigma_2 \in \mathcal{D}(U)[\Sigma]$. There is a unique integral 3-current $T(\Sigma_1, \Sigma_2)$ satisfying
\begin{equation}\label{eqn:rel_current}
    \partial T(\Sigma_1, \Sigma_2) = [\Sigma_1] - [\Sigma_2]\ \ \text{and}\ \ \mathrm{spt}(T(\Sigma_1, \Sigma_2)) \subset \overline{U} \cup \bigcup_{\Lambda} K_{\Lambda},
\end{equation}
where $\Lambda$ are the components of $\Sigma \setminus U$ with $\Lambda \cap \partial \Sigma = \varnothing$, and $K_{\Lambda}$ is the corresponding set from Lemma \ref{lem:area_comparison}.

\label{def:fill-in}
We call $T(\Sigma_1, \Sigma_2)$ from Proposition \ref{prop:fill-in} the \emph{fill-in} of $\Sigma_1$ and $\Sigma_2$. We let $F: I_3(M, \mathbb{Z}) \to L^1(M, \mathbb{Z})$ denote the canonical isomorphism of normed linear spaces, and we define the \emph{fill-in integral} as
\begin{equation}\label{eqn:fill-in_h}
    T_h(\Sigma_1, \Sigma_2) \coloneqq \int_{M} h\ F(T(\Sigma_1, \Sigma_2))\ d\mathcal{H}^3.
\end{equation}

\label{prop:fill-in_properties}
Let $\Sigma \in \mathcal{D}^*(U)$. For $\Sigma_1,\ \Sigma_2,\ \Sigma_3 \in \mathcal{D}(U)[\Sigma]$, we have
\begin{align}\label{eqn:fill-in_antisym}
    T(\Sigma_1, \Sigma_2) & = -T(\Sigma_2, \Sigma_1),\\
    T_h(\Sigma_1, \Sigma_2) & = -T_h(\Sigma_2, \Sigma_1),\notag
\end{align}
\begin{align}\label{eqn:fill-in_cyclic}
    T(\Sigma_1, \Sigma_2) + T(\Sigma_2, \Sigma_3) & = T(\Sigma_1, \Sigma_3),\\
    T_h(\Sigma_1, \Sigma_2) + T_h(\Sigma_2, \Sigma_3) & = T_h(\Sigma_1, \Sigma_3).\notag
\end{align}

\label{question:main}
If $\{\Sigma_k\}_{k \in \mathbb{N}} \subset \mathcal{D}^*(U)$ satisfies
\begin{equation}\label{eqn:min_seq_setup_disk}
    \mathcal{H}^2(\Sigma_k) \leq \mathcal{H}^2(\Sigma_k') + T_h(\Sigma_k, \Sigma_k') + \varepsilon_k
\end{equation}
for all $\Sigma_k' \in \mathcal{D}(U)[\Sigma_k]$ with $\varepsilon_k \to 0$, does (a subsequence of) $\Sigma_k$ converge to a regular limit with prescribed mean curvature $h$?

\label{thm:compactness}
Suppose $\{\Sigma_k\}_{k \in \mathbb{N}} \subset \mathcal{D}^*(U)$ satisfies
\begin{equation}\label{eqn:min_seq_compactness}
    \mathcal{H}^2(\Sigma_k) \leq \mathcal{H}^2(\Sigma_k') + T_h(\Sigma_k, \Sigma_k') + \varepsilon_k
\end{equation}
for all $\Sigma_k' \in \mathcal{D}(U)[\Sigma_k]$ with $\varepsilon_k \to 0$. Let $\Omega_k \subset U$ be the open set satisfying
\[ \partial [\Omega_k] \llcorner U =  [\Sigma_k] \llcorner U. \]

If $\sup_k \mathcal{H}^2(\Sigma_k \cap U) < \infty$, then there is a subsequence (not relabeled), a set of finite perimeter $\Omega \subset U$, and a varifold $V$ in $U$ so that
\[ \mathbf{1}_{\Omega_k} \xrightarrow{L^1} \mathbf{1}_{\Omega},\ \ D\mathbf{1}_{\Omega_k} \overset{\ast}{\rightharpoonup} D\mathbf{1}_{\Omega},\ \ \mathbf{v}(\Sigma_k \cap U) \rightharpoonup V. \]

Furthermore,
\begin{itemize}
    \item $\Omega$ and $V$ satisfy
    \begin{equation}\label{eqn:variational}
        \|V\|(U) - \int_{\Omega} h\ d\mathcal{H}^3 \leq \|\phi_{\#}V\|(U) - \int_{\phi(\Omega)} h\ d\mathcal{H}^3
    \end{equation}
    for any diffeomorphism $\phi$ of $U$ equal to the identity outside a compact subset of $U$.
    \item the first variation of $V$ satisfies
    \begin{equation}\label{eqn:first_variation_formula}
        \delta V(X) = \int_{\partial^*\Omega} X \cdot h\nu_{\partial^*\Omega}\ d|D\mathbf{1}_{\Omega}|
    \end{equation}
    for any $C^1$ vector field $X$ with $\mathrm{spt}(X) \subset\subset U$.
    \item $V$ has $c$-bounded first variation, in the sense that
    \begin{equation}\label{eqn:bounded_first_variation}
        \|\delta V\|(B_r(x)) \leq c\|V\|(B_r(x))
    \end{equation}
    for all $B_r(x) \subset U$.
    \item The function
    \begin{equation}\label{eqn:monotonicity}
        r \mapsto f(r)\frac{\|V\|(B_r(x))}{\pi r^2}
    \end{equation}
    is monotone increasing in $r$, where $f$ is a continuous function depending only on $c$ and $(M,g)$ satisfying $f(r) \to 1$ as $r \to 0$.
\end{itemize}

\label{lem:resolution}
Let $U\subset M$ be a bounded connected open set with $C^1$ boundary. Let $\mathcal{S} = \{D_i\}_{i=1}^n \in \mathcal{Y}$. Then there are Lipschitz disks $\tilde{\mathcal{S}} = \{\tilde{D}_i\}_{i=1}^n \in \mathcal{Y}_0$ with $\tilde{D}_i \subset U$ and $\partial \tilde{D}_i = \partial D_i$ satisfying
\[ \bigcup_{i=1}^n D_i = \bigcup_{i=1}^n \tilde{D}_i. \]

\label{lem:y0}
Let $U \subset M$ be an open set with $\overline{U} \approx  \overline{\mathbb{B}}$. Let $\Sigma \in \mathcal{D}(U)$. Let $\{D_i\}_{i=1}^n$ be a set of smooth embedded disks with $D_i \subset U$, $\partial D_i \subset \partial U$, and 
\[ \Sigma \cap U = \bigcup_{i=1}^{n} D_i. \]
Let $\{\tilde{D}_i\} \in \mathcal{Y}_0$ satisfy $\tilde{D}_i \subset U$ and $\partial [\tilde{D}_i] = \partial [D_i]$. Then there is an open set $\tilde{\Omega} \subset U$ satisfying
\begin{equation}\label{eqn:y0_conclusion}
\partial [\tilde{\Omega}]\llcorner U = \sum_{i=1}^n [\tilde{D}_i].
\end{equation}
Moreover, for any $\varepsilon > 0$ there is a $\Sigma' \in \mathcal{D}(U)[\Sigma]$ satisfying
\begin{equation}\label{eqn:y0_subset}
    \Sigma \triangle \Sigma' \subset U,
\end{equation}
\begin{equation}\label{eqn:y0_area}
    \mathcal{H}^2(\Sigma' \cap U) \leq \sum_{i=1}^n \mathcal{H}^2(\tilde{D}_i) + \varepsilon,
\end{equation}
and
\begin{equation}\label{eqn:y0_vol}
    \mathbb{M}(T(\Sigma, \Sigma') - ([\Omega] - [\tilde{\Omega}])) \leq \varepsilon.
\end{equation}

\label{lem:resolution_iso_collapse}
Let $U \subset M$ be an open set with $\overline{U} \approx  \overline{\mathbb{B}}$. Let $\Sigma \in \mathcal{D}(U)$. Let $\mathcal{S}$ be a set of smooth embedded disks $D$ with $D \subset U$, $\partial D \subset \partial U$, and
\[ \Sigma \cap U = \bigcup_{D \in \mathcal{S}} D. \]
Let $\mathcal{S}_0 \subset \mathcal{S}$. For $D \in \mathcal{S}_0$, let $F_D \subset \partial U$ be the isoperimetric region for $\partial D$, and let $\Lambda_D$ be the region in $U$ bounded by $D \cup F_D$. For any $\varepsilon > 0$, there is a $\Sigma' \in \mathcal{D}(U)[\Sigma]$ satisfying
\begin{equation}\label{eqn:resolution_iso_collapse_subset}
    \Sigma \triangle \Sigma' \subset U,
\end{equation}
\begin{equation}\label{eqn:resolution_iso_collapse_area}
    \mathcal{H}^2(\Sigma' \cap U) \leq \sum_{D \in \mathcal{S}_0} \mathcal{H}^2(F_D) + \sum_{D \in \mathcal{S} \setminus \mathcal{S}_0} \mathcal{H}^2(D) + \varepsilon,
\end{equation}
and
\begin{equation}\label{eqn:resolution_iso_collapse_vol}
    \mathbb{M}(T(\Sigma, \Sigma')) \leq \sum_{D \in \mathcal{S}_0} \mathcal{H}^3(\Lambda_D) + \varepsilon.
\end{equation}

\label{lem:resolution_stacked_one}
Fix some $1 \leq j \leq n$. Let $D_j' \in \mathcal{D}(U)[D_j]$ so that $D_j'$ has transverse intersections with each $D_i$ for $i \neq j$. For any $\varepsilon > 0$, there is a $\Sigma' \in \mathcal{D}(U)[\Sigma]$ satisfying
\begin{equation}\label{eqn:resolution_stacked_one_subset}
    \Sigma \triangle \Sigma' \subset U,
\end{equation}
\begin{equation}\label{eqn:resolution_stacked_one_area}
    \mathcal{H}^2(\Sigma' \cap U) \leq \mathcal{H}^2(D_j') + \sum_{i\neq j} \mathcal{H}^2(D_i) + \varepsilon,
\end{equation}
and
\begin{equation}\label{eqn:resolution_stacked_one_vol1}
    \mathbb{M}(T(\Sigma, \Sigma') - [\Omega^+] + [\Omega^-]) \leq \varepsilon,
\end{equation}
where $\Omega^+$ and $\Omega^-$ are disjoint sets contained in $\Omega_j \triangle \Omega_j'$.

Moreover, instead of (\ref{eqn:resolution_stacked_one_vol1}), we can construct $\Sigma'$ satisfying
\begin{equation}\label{eqn:resolution_stacked_one_vol2}
    \mathbb{M}(T(\Sigma, \Sigma') - ([\Omega_j] - [\Omega_j']) - [(\Omega_j' \setminus \Omega_j) \cap \Omega] +G) \leq \varepsilon.
\end{equation}
where $G$ is a nonnegative integral current, in the sense that $\int F(G)f\ d\mathcal{H}^3\geq 0$ for all nonnegative $f$.

\label{lem:resolution_decompose_one}
Suppose $D_1$ is oriented up. Let $D_1' \in \mathcal{D}(U)[D_1]$ so that $D_1'$ has transverse intersections with each $D_i$. For any $\varepsilon > 0$, there is a $\Sigma' \in \mathcal{D}(U)[\Sigma]$ satisfying
\begin{equation}\label{eqn:resolution_1-stack_subset}
    \Sigma \triangle \Sigma' \subset U,
\end{equation}
\begin{equation}\label{eqn:resolution_1-stack_area}
    \mathcal{H}^2(\Sigma' \cap U) \leq \mathcal{H}^2(D_1') + \sum_{i=2}^n \mathcal{H}^2(D_i) + \varepsilon,
\end{equation}
and
\begin{equation}\label{eqn:resolution_1-stack_vol}
    \mathbb{M}(T(\Sigma, \Sigma') - ([\Omega_1] - [\Omega_1']) + 2[\Omega_1 \setminus (\Omega \cup \Omega_1')]) \leq \varepsilon.
\end{equation}

\label{lem:resolution_decompose_two}
Suppose $D_j$ is oriented down and $D_{j+1}$ is oriented up. Let $D_j' \in \mathcal{D}(U)[D_j]$ and $D_{j+1}' \in \mathcal{D}(U)[D_{j+1}]$ be mutually disjoint and have transverse intersections with each $D_i$. For any $\varepsilon > 0$, there is a $\Sigma' \in \mathcal{D}(U)[\Sigma]$ satisfying
\begin{equation}\label{eqn:resolution_2-stacks_subset}
    \Sigma \triangle \Sigma' \subset U,
\end{equation}
\begin{equation}\label{eqn:resolution_2-stacks_area}
    \mathcal{H}^2(\Sigma' \cap U) \leq \mathcal{H}^2(D_j') + \mathcal{H}^2(D_{j+1}') + \sum_{i\notin \{j,j+1\}} \mathcal{H}^2(D_i) + \varepsilon,
\end{equation}
and
\begin{equation}\label{eqn:resolution_2-stacks_vol}
    \mathbb{M}(T(\Sigma, \Sigma') - (([\Omega_j] + [\Omega_{j+1}]) - ([\Omega_j'] + [\Omega_{j+1}'])) + 2[\Omega_j \cup \Omega_{j+1} \setminus (\Omega \cup \Omega_j' \cup \Omega_{j+1}')]) \leq \varepsilon.
\end{equation}

\label{prop:iso+PMC_controls_area}
If $\Omega \subset M$ is a set of finite perimeter with $\mathcal{H}^3(\Omega) \leq \eta$, then
\begin{equation}\label{eqn:iso}
    \mathcal{H}^3(\Omega) \leq c_1\mathcal{H}^2(\partial \Omega)^{3/2},
\end{equation}
and
\begin{equation}\label{eqn:PMC_controls_area}
    \mathcal{A}^h(\Omega) \geq \mathcal{A}^c(\Omega) \geq \frac{1}{2}\mathcal{H}^2(\partial \Omega).
\end{equation}

If $\mathcal{H}^2(\partial \Omega) \geq \delta^2$, then \eqref{eqn:iso} holds trivially by the definition of $\eta$. On the other hand, if $\mathcal{H}^2(\partial \Omega) < \delta^2$, Lemma \ref{lem:thin_isoperimetric_MSY} directly implies (\ref{eqn:iso}). Then (\ref{eqn:PMC_controls_area}) follows, as we have
\begin{align*}
    \mathcal{A}^c(\Omega) = \mathcal{H}^2(\partial \Omega) - c\mathcal{H}^3(\Omega)
    &\geq \mathcal{H}^2(\partial \Omega)(1 - cc_1^{2/3}\mathcal{H}^3(\Omega)^{1/3}) \geq \frac{1}{2}\mathcal{H}^2(\partial \Omega).
\end{align*}
The bound $\mathcal{A}^h(\Omega) \geq \mathcal{A}^c(\Omega)$ holds because $h \leq c$.

\label{lem:replacement}
Let $\xi > 0$. Suppose $\mathcal{H}^3(U) \leq \eta$. Let $\Sigma \in \mathcal{D}^*(U)$. Then there exists $\tilde{\Sigma} \in \mathcal{D}(U)[\Sigma]$ and an open subset $B \subset U$ with $\overline{B} \cap \tilde{\Sigma} = \varnothing$ such that
\begin{equation}\label{eqn:replace_subset}
    (\tilde{\Sigma} \cup \partial B) \cap U_{\xi} = \Sigma \cap U_{\xi},
\end{equation}
\begin{equation}\label{eqn:replace_inequality}
    \mathcal{H}^2(\tilde{\Sigma}) + T_h(\Sigma, \tilde{\Sigma}) \leq \mathcal{H}^2(\tilde{\Sigma}) + T_h(\Sigma, \tilde{\Sigma}) + \mathcal{H}^2(\partial B) - c\mathcal{H}^3(B) \leq \mathcal{H}^2(\Sigma),
\end{equation}
and there is a set of disjoint oriented disks $\mathcal{S}$ with
\begin{equation}\label{eqn:replace_disks}
    [\tilde{\Sigma}] \llcorner U = \sum_{D \in \mathcal{S}} [D].
\end{equation}

Suppose additionally that
\begin{equation}\label{eqn:almost_min_prereplace}
    \mathcal{H}^2(\Sigma) \leq \mathcal{H}^2(\Sigma') + T_h(\Sigma, \Sigma') + \varepsilon
\end{equation}
for all $\Sigma' \in \mathcal{D}(U)[\Sigma]$. Then
\begin{equation}\label{eqn:almost_min_postreplace}
    \mathcal{H}^2(\tilde{\Sigma}) \leq \mathcal{H}^2(\Sigma') + T_h(\tilde{\Sigma}, \Sigma') + \varepsilon
\end{equation}
for all $\Sigma' \in \mathcal{D}(U)[\tilde{\Sigma}]$, and
\begin{equation}\label{eqn:replace_diff}
    \mathcal{H}^2((\Sigma \triangle \tilde{\Sigma}) \cap U_{\xi}) \leq 2\varepsilon.
\end{equation}

Let $P \subset \Sigma \cap U$ be a union of components of $\Sigma \cap U$. Let $\mathcal{S}_P \subset \mathcal{S}$ be the collection of disks $D \in \mathcal{S}$ with $D \cap U_{\xi} \subset P$, and let $\tilde{P} \coloneqq \bigcup_{D \in \mathcal{S}_P} D$. Then
\begin{equation}\label{eqn:replace_length}
    \mathcal{H}^1\Big(\overline{\tilde{P}} \cap \partial U\Big) \leq \mathcal{H}^1(\overline{P} \cap \partial U)
\end{equation}
and
\begin{equation}\label{eqn:replace_area}
    \mathcal{H}^2(P) \leq \mathcal{H}^2(\tilde{P}) + 2\varepsilon.
\end{equation}

\label{lem:filigree}
Suppose $\mathcal{H}^3(U(\theta)) \leq \eta$. Let $\Sigma \in \mathcal{D}^*(U(\theta))$ satisfy
\begin{equation}\label{eqn:filigree_area_assumption}
    \mathcal{H}^2(\partial U(\theta)) + \mathcal{H}^2(\Sigma \setminus U) \leq \delta_1^2/32
\end{equation}
and
\begin{equation}\label{eqn:almost_min_filigree}
    \mathcal{H}^2(\Sigma) \leq \mathcal{H}^2(\Sigma') + T_h(\Sigma, \Sigma') + \varepsilon
\end{equation}
for all $\Sigma' \in \mathcal{D}(U)[\Sigma]$. Let $P$ be a union of some components of $\Sigma \cap U(\theta)$. If
\[ \mathcal{H}^2(P) \leq \frac{\theta^2}{48\beta} \]
then
\[ \mathcal{H}^2(P \cap U) \leq 6\varepsilon. \]

\label{lem:rectifiability}
Let $\{\Sigma_k\}_{k\in\mathbb{N}} \subset \mathcal{D}^*(U)$ satisfy $\mathcal{H}^2(\Sigma_k) \leq \delta_2^2/64$ and
\begin{equation}\label{eqn:min_seq_rectifiability}
    \mathcal{H}^2(\Sigma_k) \leq \mathcal{H}^2(\Sigma_k') + T_h(\Sigma_k, \Sigma_k') + \varepsilon_k
\end{equation}
for all $\Sigma_k' \in \mathcal{D}(U)[\Sigma_k]$ with $\varepsilon_k \to 0$. Let $V$ be the subsequential varifold limit of $\Sigma_k$ in $U$ provided by Theorem \ref{thm:compactness}. Then
\[ \Theta^2(\|V\|, x) \geq \frac{1}{1000\beta} > 0 \]
for all $x \in \mathrm{spt}\|V\|$. Moreover, $V$ is rectifiable.

\label{thm:local_regularity}
Let $\{\Sigma_k\}_{k\in\mathbb{N}} \subset \mathcal{D}^*(U)$ satisfy $\sup_k \mathcal{H}^2(\Sigma_k \cap U) \leq \delta_2^2/64$ and
\begin{equation}\label{eqn:min_seq_regularity}
    \mathcal{H}^2(\Sigma_k) \leq \mathcal{H}^2(\Sigma_k') + T_h(\Sigma_k, \Sigma_k') + \varepsilon_k
\end{equation}
for all $\Sigma_k' \in \mathcal{D}(U)[\Sigma_k]$ with $\varepsilon_k \to 0$. Let $V$ and $\Omega$ respectively be the subsequential varifold limit of $\Sigma_k \cap U$ and the subsequential Caccioppoli set limit of $\Omega_k$ provided by Theorem \ref{thm:compactness}. Let $\alpha\in (0,1)$.

$V$ is an integer rectifiable varifold with $c$-bounded first variation. For every $x \in \mathrm{spt}\|V\|$, we have $\Theta^2(\|V\|, x) = n_x \in \mathbb{N}$. If $h(x) \neq 0$, then $n_x \in \{1\} \cup 2\mathbb{N}$. For every $x \in \mathrm{spt}\|V\|$, there is a neighborhood $W_x$ of $x$ so that the following hold.

\begin{itemize}
    \item $V \llcorner G(W_x,2) = \sum_{l=1}^{n_x}\mathbf{v}(N_l, 1)$, where $N_l \subset W_x$ is a $C^{1,\alpha}$ surface with $c$-bounded first variation. Moreover, each $N_l$ is on one side of $N_{l'}$ intersecting tangentially at $x$ for any $l,\ l' \in \{1, \hdots, n_x\}$.
    \item If $n_x = 1$, then
    \begin{itemize}
        \item $\|V\| \llcorner W_x = |D\mathbf{1}_{\Omega}| \llcorner W_x$,
        \item $V \llcorner G(W_x,2) = \mathbf{v}(N, 1)$, where $N \subset W_x$ is a smooth stable surface with prescribed mean curvature $h$ with respect to the set $\Omega \cap W_x$.
    \end{itemize}
    \item If $h(x) \neq 0$ and $n_y = 2n$ for all $y \in \mathrm{spt}\|V\| \cap W_x'$ for an open set $W_x' \subset W_x$ containing $x$, then $V \llcorner G(W'_x,2) = \mathbf{v}(N, 2n)$, where $N\subset W_x'$ is a smooth stable minimal surface. Moreover, $\Omega \cap W_x' = W_x' \setminus N$ if $h(x) > 0$, and $\Omega \cap W_x' = \varnothing$ if $h(x) < 0$.
    \item If $h(x) \neq 0$, $n_x = 2n$, and there is a sequence $x_j \to x$ with $x_j \in \mathrm{spt}\|V\|$ and $n_{x_j} \neq 2n$, then $n = 1$ and the surfaces $N_1,\ N_2 \subset W_x$ additionally satisfy that the generalized mean curvature of $N_1$ points towards $N_2$ and vice versa.
\end{itemize}

By Lemma \ref{lem:rectifiability}, $V$ is rectifiable and has a uniform positive density lower bound in its support. By Theorem \ref{thm:compactness}(\ref{eqn:bounded_first_variation}), $V$ has $c$-bounded first variation.


\emph{Integer Density}. We show that the density of $V$ is an integer at every $x \in \mathrm{spt}\|V\|$. Since this result concerns the infinitesimal behavior of $V$ near $x$, we push objects to $T_xM$ using the exponential map $\phi_x$. In $T_xM$, we use the standard Euclidean metric in the geodesic normal coordinates, which is the $C^{\infty}$ limit of the pullback metric under a blow up rescaling.

First, let $x \in \mathrm{spt}\|V\|$ be such that there is a tangent cone $C \in \mathrm{VarTan}(V,x)$ with $\mathrm{spt}\|C\| \subset P_C$, where $P_C$ is a 2-plane in $T_xM$ (by rectifiability, this holds $\|V\|$-almost everywhere).

Fix any $\xi > 0$.

Without loss of generality, assume $P_C \supset \mathrm{spt}\|C\|$ is the $x_1x_2$-plane in $T_xM$.

Let $\mu_t$ denote the transformation of $T_xM$ given by $\mu_t(y) = ty$. By the definition of $C$, there is a sequence $\{r_j\} \to \infty$ so that
\begin{equation}\label{eqn:var_tan}
    (\mu_{r_j}\circ \phi_x^{-1})_{\#}V \rightharpoonup C
\end{equation}
as $j \to \infty$. We always assume $r_j \geq 1$.

By the lower density bound from Lemma \ref{lem:rectifiability} and the monotonicity of (\ref{eqn:monotonicity}), there is a sequence $\{\sigma_j\} \to 0$ so that
\begin{equation}\label{eqn:flat}
    (B_{1}^{\mathbb{R}^2}(0) \times (-2, 2)) \cap \mathrm{spt}\|(\mu_{r_j}\circ \phi_x^{-1})_{\#}V\| \subset B_{1}^{\mathbb{R}^2}(0) \times (-\sigma_j/2, \sigma_j/2).
\end{equation}

We establish some notation. To distinguish objects in $T_xM$ from objects in $M$, we use lower case letters here. Let
\begin{itemize}
    \item $v^j \coloneqq (\mu_{r_j} \circ \phi_x^{-1})_{\#}V$,
    \item $s_{k,j} \coloneqq (\mu_{r_j} \circ \phi_x^{-1})(\Sigma_k)$,
    \item $b_{\rho} \coloneqq B_{\rho}^{T_xM}(0)$,
    \item $c_{\rho, \sigma} \coloneqq \partial b_{\rho} \cap \{x_3 \in [-\sigma, \sigma]\}$,
    \item $d_{\rho, \sigma}^+ \coloneqq \partial b_{\rho} \cap \{x_3 > \sigma\}$,
    \item $d_{\rho, \sigma}^- \coloneqq \partial b_{\rho} \cap \{x_3 < -\sigma\}$.
\end{itemize}

By (\ref{eqn:flat}), we have
\begin{equation}\label{eqn:noarea}
    \limsup_k \mathcal{H}^2(s_{k,j} \cap (B_1^{\mathbb{R}^2}(0) \times ([-1,1] \setminus (-\sigma_j/2, \sigma_j/2)))) = 0.
\end{equation}

By (\ref{eqn:noarea}) and the coarea formula, for almost every $\rho < 1$ we have
\begin{equation}\label{eqn:nolength}
\limsup_k \mathcal{H}^1(s_{k,j} \cap (d_{\rho, \sigma_j/2}^+ \cup d_{\rho,\sigma_j/2}^-)) = 0
\end{equation}
for every $j$. Fix some $\rho_1 \in (3/4, 1)$ satisfying (\ref{eqn:nolength}) so that $s_{k,j}$ has transverse intersection with $\partial b_{\rho_1}$ for every $k$ and $j$, which is guaranteed by Sard's theorem.

Fix some $\zeta > 0$. For $k\geq k_1(j, \zeta, \rho_1)$, we have
\begin{equation}\label{eqn:length_in_caps}
    \mathcal{H}^1(s_{k,j} \cap (d_{\rho_1, \sigma_j/2}^+ \cup d_{\rho_1, \sigma_j/2}^-)) < \zeta.
\end{equation}
For $\zeta \leq \zeta_1(M)$, the coarea formula gives
\begin{equation}\label{eqn:int_in_edge}
    s_{k,j} \cap (\partial d_{\rho_1, \sigma_{k,j}}^+ \cup \partial d_{\rho_1, \sigma_{k,j}}^-) = \varnothing,
\end{equation}
for a sequence $\sigma_{k,j} \in (\sigma_j/2, \sigma_j)$.

We apply Lemma \ref{lem:replacement} to $s_{k,j} \in \mathcal{D}^*(b_{\rho_1})$ with constant $\xi$. We obtain the replacement $\tilde{s}_{k,j} \in \mathcal{D}(b_{\rho_1})[s_{k,j}]$ and a collection of disks $\mathfrak{S}_{k,j}$ composing $\tilde{s}_{k,j}$ in $b_{\rho_1}$.

Let $\xi' \in [\xi, 2\xi]$ so that
\begin{equation}\label{eqn:transverse}
    \|v^j\|(\partial b_{\rho_1 - \xi'}) = 0
\end{equation}
for all $j$.

By Lemma \ref{lem:replacement}(\ref{eqn:replace_subset}) and (\ref{eqn:replace_diff}) (also using (\ref{eqn:transverse})), we have
\begin{equation}\label{eqn:regularity_replace}
v^j \llcorner G(b_{\rho_1-\xi'},2)
= \lim_k \sum_{d \in \mathfrak{S}_{k,j}} \mathbf{v}(d \cap b_{\rho_1-\xi'}).
\end{equation}

Step 1: We show that we can throw away disks $d \in \mathfrak{S}_{k,j}$ with boundary in the caps $d_{\rho_1, \sigma_{k,j}}^{\pm}$. Let $\mathfrak{C}_{k,j}$ be the set of all such disks in $\mathfrak{S}_{k,j}$. For every $d \in \mathfrak{C}_{k,j}$, let $f_d$ be the isoperimetric region for $\partial d$ in $d_{\rho_1, \sigma_{k,j}}^+ \cup d_{\rho_1, \sigma_{k,j}}^-$. By (\ref{eqn:length_in_caps}) and Lemma \ref{lem:replacement}(\ref{eqn:replace_length}), we have
\[ \sum_{d \in \mathfrak{C}_{k,j}} \mathcal{H}^1(\partial d) \leq \zeta \]
for $k \geq k_1(j, \zeta, \rho_1)$. By the isoperimetric inequality in the round sphere, we have
\[ \mathcal{H}^2(f_d) \leq \beta_1 \mathcal{H}^1(\partial d)^2 \]
for all $d \in \mathfrak{C}_{k,j}$. Hence, we have
\[ \sum_{d \in \mathfrak{C}_{k,j}} \mathcal{H}^2(f_d) \leq \beta_1 \sum_{d \in \mathfrak{C}_{k,j}} \mathcal{H}^1(\partial d)^2 \leq \beta_1 \left(\sum_{d \in \mathfrak{C}_{k,j}} \mathcal{H}^1(\partial d)\right)^2 \leq \beta_1 \zeta^2 \]
for $k \geq k_1(j, \zeta, \rho_1)$. Consider the competitor given by replacing each $d \in \mathfrak{C}_{k,j}$ by $f_d$ (and then resolving the overlaps without increasing area by more than $\varepsilon_k$ by \cite[Corollary 1]{AS}). By (\ref{eqn:min_seq_regularity}), Lemma \ref{lem:replacement}(\ref{eqn:almost_min_postreplace}), and the fact that $|d\phi_x|\raisebox{-.2em}{$\big\vert_{B_{\rho/r_j}^M(x)}$} \leq 1 + o_j(1)$, we have
\begin{multline*}
    r_j^{-2}\sum_{d\in \mathfrak{S}_{k,j}} \mathcal{H}^2(d) \leq r_j^{-2}\sum_{d \in \mathfrak{S}_{k,j} \setminus \mathfrak{C}_{k,j}} \mathcal{H}^2(d) + r_j^{-2}\sum_{d \in \mathfrak{C}_{k,j}} \mathcal{H}^2(f_d) + 2cr_j^{-3}\mathcal{H}^3(b_{\rho_1}) + 2\varepsilon_k + o(r_j^{-2}).
\end{multline*}  
Rewriting, we have
\begin{equation}\label{eqn:disks_in_caps}
    \sum_{d\in \mathfrak{C}_{k,j}} \mathcal{H}^2(d) \leq \beta_1\zeta^2 + \frac{2c\mathcal{H}^3(b_1)}{r_j} + 2r_j^2\varepsilon_k + o_j(1)
\end{equation}
for $k \geq k_1(j, \zeta, \rho_1)$. Taking $j \geq j_2(M, \xi)$ and $\zeta \leq \zeta_2(M, \xi)$, and then taking $k \geq k_2(j, \zeta, \rho_1, \xi)$, we can apply Lemma \ref{lem:filigree} to conclude that
\[ \lim_k \sum_{d \in \mathfrak{C}_{k,j}} \mathbf{v}(d \cap b_{\rho_1 - \xi}) = 0 \]
for all $j\geq j_2(M, \xi)$.

Step 2: We show that we can throw away the disks with nullhomotopic boundary in $c_{\rho_1, \sigma_{k,j}}$. Let $\mathfrak{N}_{k,j}$ be the set of all such disks in $\mathfrak{S}_{k,j}$. By the monotonicity of (\ref{eqn:monotonicity}), there is a uniform upper bound for the mass of $v^j$ in $b_{1}$ for all $j$ depending on $V$ and $c$.

Let $\mathfrak{N}_{k,j}^{-} \subset \mathfrak{N}_{k,j}$ be the set of disks $d \in \mathfrak{N}_{k,j}$ with $\mathcal{H}^2(d) \leq \frac{\xi^2}{48\beta_1}$. By the uniform mass upper bound, there is an $m = m(V, c, \xi) \in \mathbb{N}$ such that
\[ \sum_{d \in \mathfrak{N}_{k,j}^{-}} \mathcal{H}^2(d) \leq m\frac{\xi^2}{48\beta_1} \]
for all $j$. By a standard counting argument, we can partition $\mathfrak{N}_{k,j}^{-}$ into $2m$ disjoint sets $\{\mathfrak{N}^{-}_{k,j,i}\}_{i=1}^{2m}$ (some potentially empty) such that
\[ \sum_{d \in \mathfrak{N}^{-}_{k,j,i}} \mathcal{H}^2(d) \leq \frac{\xi^2}{48\beta_1}. \]
By Lemma \ref{lem:filigree}, we have
\[ \lim_{k} \sum_{d \in \mathfrak{N}_{k,j}^{-}} \mathbf{v}(d \cap b_{\rho_1-\xi}) = \sum_{i=1}^{2m} \lim_{k} \sum_{d \in \mathfrak{N}_{k,j,i}^{-}} \mathbf{v}(d \cap b_{\rho_1-\xi}) = 0. \]

Let $\mathfrak{N}^{+}_{k,j}$ denote the set of disk $d \in \mathfrak{N}_{k,j}$ with $\mathcal{H}^2(d) > \frac{\xi^2}{48\beta_1}$. By the uniform mass upper bound, we have $\#\mathfrak{N}_{k,j}^{+} \leq m$. Let $f_d$ denote the isoperimetric region in $c_{\rho_1, \sigma_{k,j}}$ for $\partial d$. Consider the competitor given by replacing $d$ with $f_d$ for all $d \in \mathfrak{N}_{k,j}^{+}$ (and then resolving overlaps without increasing area by more than $\varepsilon_k$  by \cite[Corollary 1]{AS}). As in step 1, (\ref{eqn:min_seq_regularity}) and Lemma \ref{lem:replacement}(\ref{eqn:almost_min_postreplace}) imply
\begin{multline*}
    r_j^{-2}\sum_{d\in \mathfrak{S}_{k,j}} \mathcal{H}^2(d) \leq r_j^{-2}\sum_{d \in \mathfrak{S}_{k,j} \setminus \mathfrak{N}_{k,j}^{+}} \mathcal{H}^2(d) + r_j^{-2}\sum_{d \in \mathfrak{N}_{k,j}^{+}} \mathcal{H}^2(f_d) + 2cr_j^{-3}\mathcal{H}^3(b_{\rho_1}) + 2\varepsilon_k + o(r_j^{-2}).
\end{multline*} 
Rewriting, we have
\begin{equation}\label{eqn:disks_in_cyl}
    \sum_{d\in \mathfrak{N}_{k,j}^{+}} \mathcal{H}^2(d)
    \leq m\mathcal{H}^2(c_{\rho_1, \sigma_j}) + \frac{2c\mathcal{H}^3(b_1)}{r_j} + 2r_j^2\varepsilon_k + o_j(1).
\end{equation}
Assuming $j \geq j_3(c,\rho_1, M, V, \xi)$ and then taking $k \geq k_3(j, \rho_1, M, \xi)$, we have $\# \mathfrak{N}_{k,j}^{+} = 0$.

Step 3: We obtain lower and upper bounds for the area of the disks whose boundary is homotopically nontrivial in $c_{\rho_1, \sigma_{k,j}}$. Let $\mathfrak{L}_{k,j}$ denote the set of such disks in $\mathfrak{S}_{k,j}$.

Let $d \in \mathfrak{L}_{k,j}$. Since $\partial d$ is homotopically nontrivial in $c_{\rho_1, \sigma_{k,j}}$, (\ref{eqn:noarea}) implies
\begin{equation}\label{eqn:area_lower_bd}
\mathcal{H}^2(d \cap b_\rho) \geq \pi (\rho - \xi)^2
\end{equation}
for $\rho \in [\rho_1-2\xi, \rho_1]$, $j \geq j_4(\rho_1, M, V, \xi)$, and $k \geq k_4(j, \rho_1, M, \xi)$.

By the uniform mass bound on the limit, there is an $m = m(c,V)$ so that $\#\mathfrak{L}_{k,j} \leq m$ for all $j \geq j_4(c,\rho_1,M, V,\xi)$ and $k \geq k_4'(j, c,\rho_1, M, V,\xi)$.

For each $d \in \mathfrak{L}_{k,j}$, let $m_d$ be the disk with $\partial m_d = \partial d$ so that $m_d \setminus b_{\rho_1} \subset c_{\rho_1, \sigma_{k,j}}$ and $m_d \cap b_{\rho_1}$ is the flat disk $d_{k,j}^* \subset b_{\rho_1}$ with boundary $\partial d_{\rho_1, \sigma_{k,j}}^+$. Note that
\[ \mathcal{H}^2(m_d) \leq \mathcal{H}^2(c_{\rho_1, \sigma_{k,j}}) + \mathcal{H}^2(d_{k,j}^*). \]
Consider the competitor given by replacing each $d \in \mathfrak{L}_{k,j}$ with $m_d$ (and then resolving overlaps using \cite[Corollary 1]{AS}). As in steps 1 and 2, (\ref{eqn:min_seq_regularity}) implies
\begin{multline*}
    r_j^{-2}\sum_{d\in \mathfrak{S}_{k,j}} \mathcal{H}^2(d) \leq r_j^{-2}\sum_{d \in \mathfrak{S}_{k,j} \setminus \mathfrak{L}_{k,j}} \mathcal{H}^2(d) + r_j^{-2}\sum_{d \in \mathfrak{L}_{k,j}} \mathcal{H}^2(m_d) + 2cr_j^{-3}\mathcal{H}^3(b_{\rho_1}) + 2\varepsilon_k + o(r_j^{-2}).
\end{multline*}  
Rewriting, we have
\begin{align*}
\sum_{d\in \mathfrak{L}_{k,j}} \mathcal{H}^2(d)
& \leq (\#\mathfrak{L}_{k,j})(\mathcal{H}^2(d_{k,j}^*) + \mathcal{H}^2(c_{\rho_1,\sigma_j})) + \frac{2c\mathcal{H}^3(b_1)}{r_j} + 2r_j^2\varepsilon_k + o_j(1).
\end{align*}
Assuming $j \geq j_5(c, \rho_1, M, V, \xi)$ and then taking $k \geq k_5(j, c, \rho_1, M, V, \xi)$, we have for every $d \in \mathfrak{L}_{k,j}$ (by (\ref{eqn:area_lower_bd}))
\begin{equation}\label{eqn:area_upper_bd}
    \mathcal{H}^2(d) \leq \pi (\rho_1+\xi)^2.
\end{equation}

Step 4: We compute the density of $V$ at $x$. By (\ref{eqn:transverse}) and the above work, we have
\[ \|v^j\|(b_{\rho_1-\xi'}) = \lim_k \sum_{d \in \mathfrak{L}_{k,j}}\mathcal{H}^2(d \cap b_{\rho_1 - \xi'}). \]
By (\ref{eqn:area_lower_bd}) and (\ref{eqn:area_upper_bd}), we have
\[ (\limsup_k \#\mathfrak{L}_{k,j}) \pi(\rho_1 - \xi)^2 \leq \|v^j\|(b_{\rho_1-\xi',j}) \leq (\liminf_k \#\mathfrak{L}_{k,j}) \pi(\rho_1 + \xi)^2. \]
Assuming $\xi$ is sufficiently small (depending on universal quantities), we have $\lim_k \#\mathfrak{L}_{k,j}$ exists, so we have $\#\mathfrak{L}_{k,j} = n_j \in \mathbb{N}$ for all $j \geq j_5(c, \rho_1, M, V, \xi)$ and $k \geq k_6(j, c, \rho_1,M,V,\xi)$. By the monotonicity of (\ref{eqn:monotonicity}), $n_j$ is decreasing for $j \geq j_6(c, \rho_1, M, V, \xi)$. By Lemma \ref{lem:rectifiability}, we have $n_j \geq 1$. Hence, we have $n_j \equiv n \geq 1$ for all $j \geq j_6'(c, \rho_1, M, V, \xi)$. Therefore, we have
\[ n - o_\xi(1) \leq \Theta^2(\|V\|, x) \leq n + o_\xi(1). \]
Since $\xi$ is arbitrary, we conclude that $\Theta^2(\|V\|,x) = n \in \mathbb{N}$, i.e. $V$ has integer density at all points $x$ in its support such that some tangent cone $C\in\mathrm{VarTan}(V,x)$ is supported in a 2-plane $P_C\subset T_xM$.


\emph{Flatness of Tangent Cones}. We now show that for all $x\in\mathrm{spt}\|V\|$, every tangent cone $C\in \mathrm{VarTan}(V,x)$ is supported in some 2-plane $P_C\subset T_xM$. 
\begin{lemma}[Flatness]\label{lem:flatness}
Let $U, \Sigma_k, V$ be as in the statement of Theorem \ref{thm:local_regularity}. If $x \in \mathrm{spt}\|V\|$ and $C \in \mathrm{VarTan}(V, x)$, then $\mathrm{spt}\|C\| \subset P_C$ for some 2-plane $P_C$.
\end{lemma}
\begin{proof}
Let $x \in \mathrm{spt}\|V\|$, and let $C \in \mathrm{VarTan}(V, x)$. There is a subsequence (not relabeled) and radii $r_k \to \infty$ so that $v^k := (\mu_{r_k}\circ \phi_x^{-1})_{\#}V \rightharpoonup C$. By selecting a further subsequence (not relabeled), the surfaces  $s_k := (\mu_{r_k}\circ \phi_x^{-1})(\Sigma_k)$ satisfy
\[ \mathbf{v}(s_k) \rightharpoonup C. \]
We can choose the subsequence so that $r_k^2\varepsilon_k \to 0$.

By Sard's theorem, we can find a radius $r > 0$ so that $b_r := b_r^{T_xM}(0)$ satisfies $s_k \in \mathcal{D}^*(b_r)$ for all $k$. Note that by (\ref{eqn:min_seq_regularity}) (and the same argument as step 1 above), we have
\[ \mathcal{H}^2(s_k) \leq \mathcal{H}^2(s_k') + r_k^{-1}T_h(s_k, s_k') + r_k^2\varepsilon_k + o_k(1) \]
for all $s_k' \in \mathcal{D}(b_r)[s_k]$.

We apply Lemma \ref{lem:replacement} to $s_k$ in $b_{r}$ with constant $\theta < r/2$, producing new disks $\tilde{s}_k$ so that
\[ \mathcal{H}^2(\tilde{s}_k) \leq \mathcal{H}^2(s_k') + r_k^{-1}T_h(\tilde{s}_k, s_k') + r_k^2\varepsilon_k + o_k(1) \]
for all $s_k' \in \mathcal{D}(b_r)[\tilde{s}_k]$. By (\ref{eqn:replace_diff}), we have
\[ \lim_{k \to \infty} \mathbf{v}(\tilde{s}_k \cap b_{r/2}) = C \llcorner G(b_{r/2}, 2). \]

Since $\tilde{s}_k \triangle s_k' \subset b_r$ for all $s_k' \in \mathcal{D}(b_r)[\tilde{s}_k]$ by Lemma \ref{lem:replacement}, we have $T_h(\tilde{s}_k, s_k') \leq c\mathcal{H}^3(b_r) < \infty$. Hence,
\[ \varepsilon_k' \coloneqq r_k^{-1}T_h(s_k, s_k') + r_k^2\varepsilon_k + o_k(1) \]
satisfies $\varepsilon_k' \to 0$, and
\begin{equation}\label{eqn:min_seq_area_flatness}
    \mathcal{H}^2(\tilde{s}_k) \leq \mathcal{H}^2(s_k') + \varepsilon_k'
\end{equation}
for all $s_k' \in \mathcal{D}(b_r)[\tilde{s}_k]$.

Since we have shown the disks $\tilde{s}_k$ are a minimizing sequence for area with respect to competitors $s_k'$ in the class $\mathcal{D}(b_r)[\tilde{s}_k]$, we can now conclude by following the proof strategy of \cite{AS}. 

Indeed, we observe that \cite[Theorem 3 and Corollary 2]{AS} hold for the area minimization problem restricted to $\mathcal{D}(b_r)[\tilde{s}_k]$. Case I and Case II in the proof of \cite[Theorem 3]{AS} follow directly from the argument in \cite{AS}.
As for Case III, note that the relevant step in the proof only uses disks obtained from the replacement procedure (which lie in our restricted set of competitors) and comparison to isoperimetric regions (also in the restricted set of competitors). The rest of the proofs are unchanged.
\end{proof}

Lemma \ref{lem:flatness}, together with the previous step of the proof, shows that $V$ has positive integer density at every point of its support.


\emph{Decomposition of $V$}. To study the local regularity of $V$, we return to work in $M$. We adapt the set up from the proof of integer density. Let $x \in \mathrm{spt}\|V\|$, $\xi > 0$, $r_j \to \infty$, $\sigma_j \to 0$, $\zeta > 0$, $\sigma_{k,j} \in (\sigma_j/2, \sigma_j)$ as above. We define
\begin{itemize}
    \item $B_{\rho, j} := B_{\rho/r_j}^M(x)$,
    \item $C_{\rho, \sigma, j} := (\mu_{r_j} \circ \phi_x^{-1})^{-1}(c_{\rho, \sigma}) \subset B_{\rho, j}$,
    \item $D_{\rho, \sigma, j}^{\pm} := (\mu_{r_j} \circ \phi_x^{-1})^{-1}(d_{\rho, \sigma}^{\pm}) \subset B_{\rho, j}$.
\end{itemize}
We apply Lemma \ref{lem:replacement} to $\Sigma_k \in \mathcal{D}^*(B_{\rho_1, j})$ with constant $\xi$, producing new disks $S_{k,j}$. By (\ref{eqn:replace_inequality}), we have
\begin{equation}\label{eqn:ah_min_interior_regularity}
    \mathcal{H}^2(S_{k,j}) \leq \mathcal{H}^2(S_{k,j}') + T_h(S_{k,j}, S_{k,j}') + \varepsilon_k
\end{equation}
for all $S_{k,j}' \in \mathcal{D}(B_{\rho_1, j})[S_{k,j}]$. Let $\mathcal{S}_{k,j}$ be the set of disks composing $S_{k,j}$ in $B_{\rho_1,j}$. Let $\mathcal{L}_{k,j} \subset \mathcal{S}_{k,j}$ be the disks with homotopically nontrivial boundary in $C_{\rho_1, \sigma_{k,j}, j}$. We translate the estimates from the proof of integer density to $M$.

Henceforth we assume $j \geq j_6'(c, \rho_1, M,V, \xi)$ and $k \geq k_6(j, c, \rho_1, M, V, \xi)$ as above. Namely, we have $\#\mathcal{L}_{k,j} = n$ for all such $j$ and $k$.

Label the disks $D \in \mathcal{L}_{k,j}$ as $\{D_{k,j,1}, \hdots, D_{k,j,n}\}$. There is a subsequence (not relabeled, after shuffling the 1 through $n$ labels) so that $\mathbf{v}(D_{k,j,i})$ converges in the varifold sense to a limit $V_{j,i}$ for $i = 1, \hdots, n$ as $k \to \infty$, satisfying
\begin{equation}\label{eqn:mass_bds}
    \|V_{j,i}\|(B_{\rho_1-2\xi,j}) \geq \pi (\rho_1 - 4\xi)^2r_j^{-2} \ \ \text{and}\ \
    \|V_{j,i}\|(B_{\rho_1, j}) \leq \pi(\rho_1 + 2\xi)^2r_j^{-2},
\end{equation}
\begin{equation}\label{eqn:spt}
    \mathrm{spt}\|V_{j,i}\| \subset (\mu_{r_j} \circ \phi_x^{-1})^{-1}(B_{\rho_1}^{T_xM}(0) \cap \{-\sigma_j \leq x_3 \leq \sigma_j\}),
\end{equation}
and
\begin{equation}\label{eqn:limit_sum_of_disks}
    V \llcorner G(B_{\rho_1-2\xi, j}, 2) = \sum_{i=1}^n V_{j,i} \llcorner G(B_{\rho_1-2\xi, j}, 2).
\end{equation}

\emph{Reduction to Stacked Disk Minimization}.
We now reduce the problem to a stacked disk minimization problem.

Let $\mathcal{E}_{k,j} \coloneqq \mathcal{S}_{k,j} \setminus \mathcal{L}_{k,j}$. For $D \in \mathcal{E}_{k,j}$ let $F_D \subset \partial B_{\rho_1,j}$ be the isoperimetric region for $\partial D$. Let $\Lambda_D \subset B_{\rho_1,j}$ be the open set bounded by $D \cup F_D$.

Steps 1 and 2 from the proof of integer density above imply
\begin{equation}\label{eqn:extra_small_area}
    \limsup_k \sum_{D \in \mathcal{E}_{k,j}} \mathcal{H}^2(D \cap B_{1/2, j}) = 0.
\end{equation}
In particular, (\ref{eqn:disks_in_caps}) and (\ref{eqn:disks_in_cyl}) imply
\begin{equation}\label{eqn:extra_small_area1}
    \mathcal{H}^2(D) + \mathcal{H}^2(F_D) \leq A(\xi, \zeta, j,k)
\end{equation}
with $A(\xi, \zeta, j, k) \to 0$ as $(\xi, \zeta) \to 0$ and $j, k \to \infty$. By (\ref{eqn:iso}), we have
\[ \mathcal{H}^3(\Lambda_D) \leq c_1A(\xi,\zeta,j,k)^{3/2}. \]
Taking $\xi$ and $\zeta$ small and $j$ and $k$ large, the coarea formula implies
\begin{equation}\label{eqn:extra_apply_iso}
    \limsup_k \mathcal{H}^2(\Lambda_D \cap \partial B_{\rho,j}) \leq \frac{1}{4}\mathcal{H}^2(\partial B_{1/4,j}) \leq \frac{1}{4}\mathcal{H}^2(\partial B_{\rho,j})
\end{equation}
for $\rho$ in a set of positive measure in $(1/4,1/2)$. By the coarea formula and (\ref{eqn:extra_small_area}), we have
\begin{equation}\label{eqn:extra_small_length}
    \limsup_k \sum_{D \in \mathcal{E}_{k,j}} \mathcal{H}^1(D \cap \partial B_{\rho,j}) = 0
\end{equation}
for almost every $\rho \in (1/4, 1/2)$. Take $\rho \in (1/4, 1/2)$ satisfying (\ref{eqn:extra_apply_iso}) and (\ref{eqn:extra_small_length}). By the coarea formula and (\ref{eqn:extra_small_length}), we have
\begin{equation}\label{eqn:extra_corner}
    \limsup_k \sum_{D \in \mathcal{E}_{k,j}} \mathcal{H}^0(D \cap \partial C_{\rho, \sigma,j}) = 0
\end{equation}
for $\sigma$ in a set of positive measure in $(\sigma_0/4, \sigma_0/2)$.

For $D \in \mathcal{E}_{k,j}$, let $B_D$ be the unique component of $D \setminus B_{\rho,j}$ containing $\partial D$. Note that $B_D$ is a punctured disk with boundary $\partial D \cup \bigcup_l \alpha_l$, where $\alpha_l$ are smooth Jordan curves in $\partial B_{\rho, j}$. Let $N_D$ be a smooth disk in $\overline{B}_{\rho_1, j} \setminus \overline{B}_{\rho, j}$ obtained by gluing $F_{\alpha_l}$ (the isoperimetric region in $\partial B_{\rho, j}$ for $\alpha_l$) to $B_D$ and then smoothing. This procedure is well-defined as long as $F_{\alpha_l}$ is glued and perturbed before $F_{\alpha_{l'}}$ if $F_{\alpha_l} \subset F_{\alpha_{l'}}$. Moreover, the resulting surface is a disk by construction.

We construct a competitor $\mathbf{S}_{k,j} \in \mathcal{D}(B_{\rho_1,j})[S_{k,j}]$ by replacing each $D \in \mathcal{E}_{k,j}$ by $N_D$. Since the surfaces $B_D$ are disjoint, we can choose the smoothing so that the surfaces $N_D$ are also disjoint, so $\mathbf{S}_{k,j}$ is well-defined.

We claim that we can replace $S_{k,j}$ by $\mathbf{S}_{k,j}$ in (\ref{eqn:ah_min_interior_regularity}) after replacing $\varepsilon_k$ by some $\varepsilon_{k,j}$ satisfying $\lim_k \varepsilon_{k,j} = 0$. Note that $N_D$ is obtained from $D$ by (a) applying Lemma \ref{lem:area_comparison} to each component of $D \setminus B_{\rho,j}$ except $B_D$, (b) deleting everything in $\overline{B}_{\rho, j}$, and (c) turning $B_D$ into $N_D$ as described above. By Lemma \ref{lem:area_comparison} and (\ref{eqn:extra_small_area1}), the $\mathcal{A}^h$ functional does not increase after (a). Since we only delete portions of the surface in (b), the area does not increase from (b). By (\ref{eqn:iso}), (\ref{eqn:prelim_isoperimetric}), and (\ref{eqn:extra_apply_iso}), we have (for $k$ large)
\begin{align*}
    \mathcal{H}^3(\Lambda_D \cap B_{\rho,j})
    & \leq c_1(\mathcal{H}^2(D \cap B_{\rho,j}) + \mathcal{H}^2(\Lambda_D \cap \partial B_{\rho,j}))^{3/2}\\
    & \leq c_1(\mathcal{H}^2(D \cap B_{\rho,j}) + \beta_0\mathcal{H}^1(D \cap \partial B_{\rho,j})^2)^{3/2}
\end{align*}
Hence, we have
\begin{align}\label{eqn:vol_decay}
    \sum_{D \in \mathcal{E}_{k,j}} & \mathcal{H}^3(\Lambda_D \cap B_{\rho,j})
    \leq c_1 \sum_{D \in \mathcal{E}_{k,j}}(\mathcal{H}^2(D \cap B_{\rho,j}) + \beta_0\mathcal{H}^1(D \cap \partial B_{\rho,j})^2)^{3/2}\notag\\
    & \leq c_1 \left(\sum_{D \in \mathcal{E}_{k,j}}(\mathcal{H}^2(D \cap B_{\rho,j}) + \beta_0\mathcal{H}^1(D \cap \partial B_{\rho,j})^2)\right)^{3/2}\\
    & \leq c_1\left(\sum_{D \in \mathcal{E}_{k,j}}\mathcal{H}^2(D \cap B_{\rho,j}) + \beta_0\left(\sum_{D \in \mathcal{E}_{k,j}}\mathcal{H}^1(D \cap \partial B_{\rho,j})\right)^2\right)^{3/2}\notag
\end{align}
and the right hand side goes to zero by (\ref{eqn:extra_small_area}) and (\ref{eqn:extra_small_length}). Therefore the volume change from (b) vanishes as $k \to \infty$. Finally, by (\ref{eqn:extra_small_length}) and (\ref{eqn:prelim_isoperimetric}), we have $\lim_k \sum_{\mathcal{E}_{k,j}} \mathcal{H}^2(N_D \triangle B_D) = 0$, so the area added in (c) vanishes as $k \to \infty$. Hence, we have
\begin{equation}\label{eqn:ah_min_new_competitor}
    \mathcal{H}^2(\mathbf{S}_{k,j}) \leq \mathcal{H}^2(S_{k,j}') + T_h(\mathbf{S}_{k,j}, S_{k,j}') + \varepsilon_{k,j}
\end{equation}
for all $S_{k,j}' \in \mathcal{D}(B_{\rho_1, j})[\mathbf{S}_{k,j}]$, where $\lim_k \varepsilon_{k,j} = 0$.

Let $D_{k,j,i}' \in \mathcal{D}(B_{\rho,j})[D_{k,j,i}]$ be mutually disjoint for $i = 1,\hdots, n$. Let $\Omega_{k,j,i}$ be the open set in $B_{\rho_1,j}$ so that
\[ \partial [\Omega_{k,j,i}] \llcorner B_{\rho_1,j} = [D_{k,j,i}] \llcorner B_{\rho_1,j}. \]
Let $\Omega_{k,j,i}'$ be the analogous open set for $D_{k,j,i}'$. We claim that
\begin{equation}\label{eqn:stacked_disks}
    \sum_i \left(\mathcal{H}^2(D_{k,j,i}) - \int_{\Omega_{k,j,i}}h\ d\mathcal{H}^3\right)\leq \sum_i \left(\mathcal{H}^2(D_{k,j,i}') - \int_{\Omega_{k,j,i}'}h\ d\mathcal{H}^3\right) + \varepsilon_{k,j}''
\end{equation}
for some $\lim_k \varepsilon_{k,j}'' \to 0$.

Consider the competitor $S_{k,j}' \in \mathcal{D}(B_{\rho_1,j})[\mathbf{S}_{k,j}]$ given by replacing each $D_{k,j,i}$ by $D_{k,j,i}'$. This competitor is well-defined (i.e. there are no self-intersections) because $(\mathbf{S}_{k,j} \setminus \bigcup_i D_{k,j,i}) \cap B_{\rho, j} = \varnothing$ by definition, and $D_{k,j,i}' \setminus \overline{B}_{\rho, j}$ is a subset of $D_{k,j,i}$. Hence, (\ref{eqn:stacked_disks}) follows directly from (\ref{eqn:ah_min_new_competitor}).

We conclude with some notation. Let $B_{k,j,i}$ be the open set in $B_{\rho_1,j}$ so that
\[ \partial B_{k,j,i} \setminus D_{k,j,i} \subset \partial B_{\rho_1,j}\ \ \text{and}\ \  D_{\rho_1, \sigma_{k,j}, j}^- \subset \partial B_{k,j,i}. \]
If $B_{k,j,i} \subset B_{k,j,i'}$ for some $i \neq i'$, then we say $D_{k,j,i} < D_{k,j,i'}$. If $B_{k,j,i} = \Omega_{k,j,i}$ (as defined above), then we say $D_{k,j,i}$ is oriented up; otherwise, it is oriented down. By selecting a subsequence and relabeling, we can assume that
\[ D_{k,j,1} > D_{k,j,2} > \hdots > D_{k,j,n}, \]
and that $D_{k,j,i}$ is oriented up if and only if $D_{k',j,i}$ is oriented up for all $k'\neq k$. By the assumption that there is an open set $\Lambda_k$ with $\partial \Lambda_k \cap U = \Sigma_k \cap U$, we conclude that $D_{k,j,i}$ is oriented up if and only if $D_{k,j,i-1}$ and $D_{k,j,i+1}$ are oriented down (i.e.\ the orientation alternates with respect to the order of the disks).

\emph{Parity for Stacked Disks}. Let $\Omega_k$ and $\Omega$ be defined as in Theorem \ref{thm:compactness} with respect to the set $U$. Let $x \in \mathrm{spt}\|V\|$. We claim that
\begin{equation}\label{eqn:even_parity}
    \Theta^2(\|V\|, x) \equiv 0 \mod 2 \implies x \notin \partial^*\Omega,
\end{equation}
and
\begin{equation}\label{eqn:odd_parity}
    \Theta^2(\|V\|, x) \equiv 1 \mod 2 \implies x \in \overline{\partial^*\Omega}.
\end{equation}

Let $W$ be any neighborhood of $x$. Taking $j$ large enough, we have $B_{\rho_1, j} \subset W$. Let $\Omega_{k,j,i}$ be defined as above for the stacked disks $D_{k,j,i}$. Let $\Omega_{k,j}$ be the open subset of $B_{\rho_1,j}$ satisfying
\[ \partial[\Omega_{k,j}]\llcorner B_{\rho_1, j} = \sum_{i=1}^n [D_{k,j,i}] \llcorner B_{\rho_1, j}. \]
Let $\Omega^{j,i}$ and $\Omega^j$ be the limits of $\Omega_{k,j,i}$ and $\Omega_{k,j}$ in $k$ respectively, in the sense of Theorem \ref{thm:compactness}.

We first show that $\mathcal{H}^3((\Omega^j \triangle \Omega)) \cap B_{\rho, j}) = 0$. Indeed, we have
\begin{align*}
    \mathcal{H}^3((\Omega^j \triangle \Omega) \cap B_{\rho, j})
    & = \lim_k \mathcal{H}^3((\Omega_{k,j} \triangle \Omega_k) \cap B_{\rho, j})\\
    & \leq \lim_k\mathcal{H}^3(\beta_k) + \sum_{D \in \mathcal{E}_{k,j}} \mathcal{H}^3(\Lambda_D \cap B_{\rho,j}) = 0,
\end{align*}
by Lemma \ref{lem:replacement}(\ref{eqn:replace_diff}) and (\ref{eqn:vol_decay}) (where $\beta_k$ are the bubbles called ``$B$'' in Lemma \ref{lem:replacement}). Hence, we have
\[ \partial^*\Omega \cap B_{\rho, j} = \partial^*\Omega^j \cap B_{\rho,j}, \]
so it suffices to work with $\Omega^j$.

Let $\omega^j := (\mu_{r_j} \circ \phi_x^{-1})(\Omega^j)$. Let $v_{j,i} := (\mu_{r_j} \circ \phi_x^{-1})_{\#}V_{j,i}$. By (\ref{eqn:spt}), we have
\[ \mathrm{spt}\left\|\sum_i v_{j,i}\right\| \cap b_{\rho} \subset b_{\rho} \cap \{-\sigma_j \leq x_3 \leq \sigma_j\}. \]
Let
\[ b_{\rho,j}^+ \coloneqq b_{\rho} \cap \{x_3 > \sigma_j\}\ \ \text{and}\ \  b_{\rho,j}^- \coloneqq b_{\rho} \cap \{x_3 < -\sigma_j\}. \]
Since $\overline{\partial^*\omega^j} \cap b_{\rho} \subset \mathrm{spt}\|\sum_iv_{j,i}\| \cap b_{\rho}$, we have either $b_{\rho,j}^+ \subset \omega^j$ or $b_{\rho,j}^+ \cap \omega^j = \varnothing$ (and analogously for $b_{\rho,j}^-$). We see that $D_{k,j,1}$ is oriented down if and only if $b_{\rho,j}^+ \subset \omega^j$. Similarly, $D_{k,j,n}$ is oriented up if and only if $b_{\rho,j}^- \subset \omega^j$. Note that $b_{\rho, j}^{\pm}$ contain a definite portion of $b_{2}^{\pm}$ (the upper and lower half balls of radius 2 in $T_xM$).

If $n \equiv 1 \mod 2$, then $\omega^j$ converges in $L^1$ as $j \to \infty$ (without loss of generality) to the upper half space $H^+ \subset T_xM$. Hence, every sufficiently small neighborhood $W$ of $x$ satisfies
\[ 0 < \mathcal{H}^3(\Omega \cap W) < \mathcal{H}^3(W), \]
so we have $x \in \overline{\partial^*\Omega}$.

If $n \equiv 0 \mod 2$, then $\omega^j$ converges in $L^1$ as $j \to \infty$ to $T_xM$ or $\varnothing$, so $x \notin \partial^*\Omega$ (i.e.\ we showed $x$ is not in the essential boundary of $\Omega$, which contains the reduced boundary (see \cite[Theorem 16.2]{maggi}).

\emph{$C^{1,\alpha}$ Regularity}. By Lemma \ref{lem:resolution_stacked_one}(\ref{eqn:resolution_stacked_one_vol1}) and (\ref{eqn:stacked_disks}), we have
\begin{equation}\label{eqn:weak_minimizing}
    \mathcal{H}^2(D_{k,j,i}) \leq \mathcal{H}^2(D_{k,j,i}') + c|T(D_{k,j,i}, D_{k,j,i'})| + \varepsilon_{k,j}
\end{equation}
for any $D_{k,j,i}' \in \mathcal{D}(B_{\rho, j})[D_{k,j,i}]$.

We observe that everything we have proved thus far only requires that the function $h$ is measurable and satisfies $|h| \leq c$. We note that (\ref{eqn:weak_minimizing}) implies that $D_{k,j,i}$ is a minimizing sequence for the problem with prescribing function $-c + 2c\mathbf{1}_{\Omega_{j,i}}$. Hence, all of the above work applies to $V_{j,i}$. In particular, $V_{j,i}$ has $c$-bounded first variation and positive integer density in its support. By (\ref{eqn:mass_bds}), there is a neighborhood $W$ of $x$ so that $\Theta^2(V_{j,i}, y) = 1$ for all $y \in W\cap \mathrm{spt}\|V_{j,i}\|$.

By \cite[\S8]{allard}, we have $V_{j,i} \llcorner G(W,2) = \mathbf{v}(N_{j,i}, 1)$ for a $C^{1.\alpha}$ surface $N_{j,i} \subset W$. By (\ref{eqn:odd_parity}), we have $N_{j,i} \cap W = \partial^*\Omega^{j,i} \cap W$. Hence, $N_{j,i}$ is on one side of $N_{j,i'}$ for any $i,\ i'$, and each of these surfaces intersects tangentially at $x$. We conclude by (\ref{eqn:limit_sum_of_disks}).

\emph{Decomposition into 1-Stacks and 2-Stacks}. Take $x$ so that $h(x) \neq 0$. Suppose without loss of generality (by swapping orientations and taking $j$ sufficiently large) that $h\vert_{B_{\rho_1, j}} > 0$. We now decompose the stacked disk minimization problem (\ref{eqn:stacked_disks}) into smaller units, which we call 1-stacks and 2-stacks.

We first separate the 1-stacks. If $D_{k,j,1}$ is oriented up, then we show that
\begin{equation}\label{eqn:1-stacks}
    \mathcal{H}^2(D_{k,j,1}) - \int_{\Omega_{k,j,1}}h\ d\mathcal{H}^3  \leq \mathcal{H}^2(D_{k,j,1}') - \int_{\Omega_{k,j,1}'}h\ d\mathcal{H}^3 + \varepsilon_{k,j}
\end{equation}
for all $D_{k,j,1}' \in \mathcal{D}(B_{\rho,j})[D_{k,j,1}]$, where $\Omega_{k,j,1}'$ is defined as above. The analogous statement holds if $D_{k,j,n}$ is oriented down by vertical reflection. The result follows immediately from Lemma \ref{lem:resolution_decompose_one}.

Now we separate the 2-stacks. If $D_{k,j,i'}$ is oriented down for some $1 \leq i' < n$, then we show that
\begin{equation}\label{eqn:2-stacks}
    \sum_{i=i'}^{i'+1} \left(\mathcal{H}^2(D_{k,j,i}) -\int_{\Omega_{k,j,i}}h\ d\mathcal{H}^3 \right) \leq \sum_{i=i'}^{i'+1} \left(\mathcal{H}^2(D_{k,j,i}') - \int_{\Omega_{k,j,i}'}h\ d\mathcal{H}^3\right) + \varepsilon_k'
\end{equation}
for all mutually disjoint $D_{k,j,i}' \in \mathcal{D}(B_{\rho, j})[D_{k,j,i}]$ for $i = i',\ i'+1$, where $\Omega_{k,j,i}'$ is defined as above. The result follows immediately from Lemma \ref{lem:resolution_decompose_two}.

\emph{Regularity of 1-Stacks}. Suppose (\ref{eqn:1-stacks}) holds\footnote{We note that (\ref{eqn:1-stacks}) holds at any point in $V$ of density 1, as well as in the case $D_{k,j,1}$ is oriented up.}. Recall that we showed $\Theta^2(V_{j,1}, y) = 1$ for all $y \in W \cap \mathrm{spt}\|V_{j,1}\|$ and
\[ \mathrm{spt}\|V_{j,1}\| \cap W = \partial^*\Omega^{j,1} \cap W. \]
Hence, we have
\[ \|V_{j,1}\| \llcorner W = |D\mathbf{1}_{\Omega^{j,1}}| \llcorner W. \]
Inserting this equality into Theorem \ref{thm:compactness}(\ref{eqn:first_variation_formula}), we conclude that
\[ H_{V_{j,1}}\vert_{W} = h\nu_{\partial^*\Omega^{j,1}}\vert_{W}, \]
which is a $C^{1,\alpha}$ vector field. Applying the regularity theorem of Allard \cite[\S8]{allard} iteratively, we conclude that $N_{j,1}$ is a smooth surface with prescribed mean curvature $h$ in $W$ with respect to the set $\Omega^{j,1}$. Stability follows from smooth embeddedness and (\ref{eqn:variational}).

\emph{Regularity of 2-Stacks}. 
Suppose $D_{k,j,i'}$ is oriented down for $1 \leq i' < n$, so (\ref{eqn:2-stacks}) holds. For ease of notation, let $i' = 1$.

We show the mean convexity of $V_{j,1}$. Let $X$ be a smooth vector field with compact support in $B_{\rho, j}$, and let $\Phi_t$ be the flow of $X$. Without loss of generality, we suppose that
\[ \frac{d}{dt}\Big|_{t = 0} \|(\Phi_t)_{\#}V_1\|(B_{\rho, j}) < 0, \]
(i.e.\ either the derivative is zero, or we can swap $X \mapsto -X$).
By Lemma \ref{lem:resolution_stacked_one}(\ref{eqn:resolution_stacked_one_vol2}) and (\ref{eqn:2-stacks}), we have (using $h \geq 0$)
\[
    \mathcal{H}^2(D_{k,j,1} \cap B_{\rho, j}) \leq \mathcal{H}^2(\Phi_t(D_{k,j,1})\cap B_{\rho, j}) + c\mathcal{H}^3(\Omega_{k,j,1} \setminus \Phi_t(\Omega_{k,j,1})) + \varepsilon_k''.
\]
Following the proof of Theorem \ref{thm:compactness}, we have
\begin{equation}\label{eqn:2-stack_bdd_first_variation1}
    \|V_{j,1}\|(B_{\rho, j}) \leq \|(\Phi_t)_{\#}V_{j,1}\|(B_{\rho,j}) + c\mathcal{H}^3(\Omega^{j,1} \setminus \Phi_t(\Omega^{j,1})).
\end{equation}
Hence, we have
\begin{equation}\label{eqn:2-stack_bdd_first_variation2}
    0 > \frac{d}{dt}\Big|_{t=0} \|(\Phi_t)_{\#}V_{j,1}\|(B_{\rho, j}) \geq -c\frac{d}{dt}\Big|_{t=0^+} \mathcal{H}^3(\Omega^{j,1} \setminus \Phi_t(\Omega^{j,1})).
\end{equation}
By \cite[Proposition 17.8]{maggi}, we have
\[ \frac{d}{dt}\Big|_{t=0^+} \mathcal{H}^3(\Omega^{j,1} \setminus \Phi_t(\Omega^{j,1})) \leq \int_{\partial^*\Omega_1} (X \cdot \nu_{\partial^*\Omega^{j,1}})_-\ d\mathcal{H}^2. \]
Hence, we observe that the first variation cannot be negative if $X \cdot \nu_{\partial^*\Omega^{j,1}} \geq 0$, which proves the desired weak mean convexity. By vertical reflection, the same holds for $V_{j,2}$.

Suppose $\mathrm{spt}\|V_{j,1}\| \cap W' = \mathrm{spt}\|V_{j,2}\| \cap W'$ for some open set $W' \subset W$. As shown above, $\Theta^2(V_{j,1} + V_{j,2}, x) = 2$ for all $x \in \mathrm{spt}\|V_{j,1} + V_{j,2}\| \cap W'$. By (\ref{eqn:even_parity}), we have $\partial^*(\Omega^{j,1} \cup \Omega^{j,2}) \cap W' = \varnothing$, so in fact $\overline{\partial^*(\Omega^{j,1} \cup \Omega^{j,2})} \cap W' = \varnothing$. Since we already showed $\mathrm{spt}\|V_{j,i}\| \cap W' = \partial^*\Omega^{j,i} \cap W'$, we conclude that $\mathcal{H}^3((\Omega^{j,1} \cup \Omega^{j,2}) \cap W') = \mathcal{H}^3(W')$. By Theorem \ref{thm:compactness}(\ref{eqn:variational}), $V_{j,1} + V_{j,2}$ is stationary in $W'$. Then by Allard's regularity theorem \cite[\S8]{allard},
\[ (V_{j,1} + V_{j,2}) \llcorner G(W',2) \cap \mathbf{v}(N, 2), \]
where $N \subset W'$ is a smooth minimal surface. Hence, $N_{j,1} \cap W' = N_{j,2} \cap W' = N$. Stability follows from smooth embeddedness and Theorem \ref{thm:compactness}(\ref{eqn:variational}).

\emph{Maximum Principle}. 
First, suppose $\Theta^2(\|V\|, x) = 2n + 1$. Then (without loss of generality) $D_{k,j,1}$ is oriented up. By the regularity of 1-stacks, $V_{j,1}$ is the varifold associated to a smooth surface $N_{j,1}$ with mean curvature $h > 0$ pointing up. Suppose for contradiction that $n \geq 1$. Then $V_{j,2}$ is the varifold associated to a $C^{1,\alpha}$ surface $N_{j,2}$ with generalized mean curvature pointing down. Moreover, $N_{j,2}$ is below $N_{j,1}$ and intersects $N_{j,1}$ tangentially at $x$, which contradicts the strong maximum principle (see Lemma \ref{lem:maximum_principle}). Hence, if $D_{k,j,1}$ is oriented up, then $n = 1$ and $V$ is the varifold of a smooth surface of prescribed mean curvature $h$ pointing up in a neighborhood of $x$.

Second, suppose $\Theta^2(\|V\|, x) = 2n$ with $n \geq 2$. By the above paragraph, $V$ consists of $n$ 2-stacks intersecting tangentially and on one side at $x$. Then $N_{j, 2}$ and $N_{j, 2n - 1}$ are $C^{1,\alpha}$ surfaces on one side of each other, intersecting tangentially at $x$, and with generalized mean curvature pointing away from each other. By the strong maximum principle (see Lemma \ref{lem:maximum_principle}) and the regularity of 2-stacks, there is a neighborhood $W''$ of $x$ and a minimal surface $N \subset W''$ satisfying $N_{j, i} \cap W'' = N$ for all $i$. Hence, $\Theta^2(\|V\|, y) = 2n$ for all $y \in W'' \cap \mathrm{spt}\|V\|$.

\label{cor:estimate}
\begin{equation}
\sum_{i=1}^n\|\tilde{u}_i\|_{C^{1,1}(\tilde{\mathcal{B}}_{1/2}(x))}\leq C\left(\sum_{i=1}^n\|\tilde{u}_i\|_{C^{1,\alpha}(\tilde{\mathcal{B}}_1(x)}+\|\tilde{h}\|_{C^1(\tilde{\mathcal{B}}_1(x)\times (-1,1))}\right)
\end{equation} 
for some constant $C \geq 1$ depending only on $n, \alpha$, and the metric $g$ in $W_x$.

\label{question:main_isotopy}
Consider a sequence $\{\Omega_k\}_{k \in \mathbb{N}} \subset \mathcal{O}(U)$ and $\Sigma_k := \partial \Omega_k \cap U$ satisfying $\sup_k \mathcal{H}^2(\Sigma_k) < \infty$, $\sup_k \mathrm{genus}(\Sigma_k) < \infty$, and
\begin{equation}\label{eqn:min_seq_setup_isotopy}
    \mathcal{A}^h(\Omega_k) \leq \mathcal{A}^h(\phi(1, \Omega_k)) + \varepsilon_k
\end{equation}
for all $\phi \in \mathcal{I}(U)$ with $\varepsilon_k \to 0$. Does (a subsequence of) $\Sigma_k := \partial \Omega_j \cap U$ converge to a regular limit with prescribed mean curvature $h$?

\label{def:gamma_reduction}
For $\Sigma_1,\ \Sigma_2 \in \mathcal{C}(\Sigma, U)$, we write
\[ \Sigma_2 \overset{(\gamma, U)}{\ll} \Sigma_1 \]
and say $\Sigma_2$ is a \emph{$\gamma$-reduction} of $\Sigma_1$ if the following hold:
\begin{enumerate}
    \item $\Sigma_2$ is obtained from $\Sigma_1$ by surgery in $U$; namely,
    \begin{itemize}
        \item $\overline{\Sigma_1 \setminus \Sigma_2} =: A$ is diffeomorphic to the standard closed annulus,
        \item $\overline{\Sigma_2 \setminus \Sigma_1} =: D_1 \cup D_2$ is diffeomorphic to the disjoint union of two standard closed disks,
        \item there is an open set $Y \subset U$ homeomorphic to the standard 3-ball with $\partial Y = A \cup D_1 \cup D_2$ and $Y \cap (\Sigma_1 \cup \Sigma_2) = \varnothing$.
    \end{itemize}
    \item $\mathcal{H}^2(A) + \mathcal{H}^2(D_1) + \mathcal{H}^2(D_2) < 2\gamma$.
    \item If $\Gamma$ is the connected component of $\Sigma_1$ containing $A$, then for each component of $\Gamma \setminus A$ we have either
    \begin{itemize}
        \item it is a disk of area at least $\delta^2/2$,
        \item it is not simply connected.
    \end{itemize}
\end{enumerate}

\label{def:strong_gamma_reduction}
For $\Sigma_1,\ \Sigma_2 \in \mathcal{C}(\Sigma, U)$, we write
\[ \Sigma_2 \overset{(\gamma, U)}{<} \Sigma_1 \]
and say $\Sigma_2$ is a \emph{strong $\gamma$-reduction} of $\Sigma_1$, if there is an isotopy $\psi \in \mathcal{I}(U)$ satisfying
\begin{enumerate}
    \item $\Sigma_2 \overset{(\gamma, U)}{\ll} \psi(1, \Sigma_1)$,
    \item $\mathcal{H}^2(\psi(1, \Sigma_1) \triangle \Sigma_1) < \gamma$.
\end{enumerate}

\label{rem:ac_to_vol}
Since $\Omega^j \subset U$ and $\mathcal{H}^3(U) \leq \eta$, we have by Proposition \ref{prop:iso+PMC_controls_area} that
\[ \mathcal{H}^3(\Omega^j) \leq c_1^{2/3}\eta^{1/3}(\mathcal{H}^2(D_j) + \mathcal{H}^2(F_{\partial D_j})). \]
By our choice of $\eta$, we have
\[ c\mathcal{H}^3(\Omega^j) \leq \frac{1}{2}(\mathcal{H}^2(D_j) + \mathcal{H}^2(F_{\partial D_j})). \]
Then conclusion (5) of Theorem \ref{thm:gamma_reduction} implies
\begin{equation}\label{eqn:area_gamma_red}
    \sum_{j=1}^p \mathcal{H}^2(D_j) \leq 3\sum_{j=1}^q \mathcal{H}^2(F_j) + 2E(\Omega).
\end{equation}

\label{def:meets_transversally}
Let $U = B_\rho(x) \subset M$ for $\rho \ll 1$ and let $\sigma \subset \partial U$ be a disjoint union of finitely many smooth Jordan curves. An open set $A \subset U$ \emph{meets $\partial U$ in $\sigma$ transversally} if there is a positive angle $\theta_0$ so that
\begin{itemize}
    \item $\partial A \cap \partial U \subset \sigma$,
    \item for every $p \in \partial A \cap \partial U$, if we choose coordinates so that $T_p \partial U = \{z = 0\}$ and $T_p\sigma = \{y = z = 0\}$, then every point $q = (q_1, q_2, q_3) \in A$ satisfies $\frac{q_3}{q_2} \geq \tan(1/2 - \theta_0)$.
\end{itemize}

\label{lem:small_curv_graph}
Let $\Sigma^2$ be a compact orientable surface (possibly with boundary) and let $f : \Sigma \to M^3$ be 2-sided $C^{1,1}$ immersion such that $f(\Sigma)\subset U$ and $f(\partial\Sigma)\subset\partial U$. Let $\nu:\Sigma\to TM$ be a (Lipschitz) choice of unit normal vector field for the immersion such that $\sup_{p\in\Sigma}\operatorname{Lip}_p\nu\leq C_0$. Then, for any $K\subset\subset U$ there is $r_K=r_K(\rho_0, \operatorname{dist}_M(K,\partial U), C_0)>0$ such that if $x=f(p)\in f(\Sigma)\cap K$ and $r \leq r_K$, then
\begin{enumerate}
    \item $\mathcal{B}^\Sigma_{2r}(p)$ can be written as the graph of a $C^{1,1}$ function $u$ over an open neighborhood of $0$ in $df_p(T_p\Sigma) \subset T_xM$, such that $|\nabla u|\leq 1$ and $\operatorname{Lip}\nabla u\leq 2\sqrt{2} C_0$,
    \item the connected component of $f^{-1}(B^M_{r}(x))$ containing $p$ is contained in $B^\Sigma_{2r}(p)$.
\end{enumerate}

A pair $(V, \Omega) \in \mathcal{P}$ is a \emph{weakly stable $h$-surface in $U$} if
\begin{itemize}
    \item $(V, \Omega)$ has the regularity of Theorem \ref{thm:main_isotopy_regularity} in $U$,
    \item for any $\phi \in \mathcal{I}(U)$, we have
    \begin{align*}
        & \left.\frac{d}{dt}\right\vert_{t = 0}  \mathcal{A}^h(\phi(t,\cdot)_{\#}V, \phi(t, \Omega)) = 0,\\
        & \left.\frac{d^2}{dt^2}\right\vert_{t = 0} \mathcal{A}^h(\phi(t,\cdot)_{\#}V, \phi(t, \Omega)) \geq 0.
    \end{align*}
\end{itemize}

\label{prop:second_variation}
If $(V, \Omega)$ is a weakly stable $h$-surface in $U$ with corresponding immersion $f : \Sigma \to U$, then for any $\psi \in C_c^{\infty}(\Sigma)$ which is the pullback by $f$ of a smooth function on $U$, we have
\begin{equation}\label{eqn:second_variation}
    \int_{\Sigma} |\nabla^{\Sigma}\psi|^2 - (|A^{\Sigma}|^2+\mathrm{Ric}_M(\nu,\nu))\psi^2\ d\mathcal{H}^2
    \geq \int_{\partial^*\Omega} (H^{\Sigma}h + \partial_{\nu}h - |H^{\Sigma}|^2)\psi^2\ d\mathcal{H}^2.
\end{equation}

\label{thm:main_estimate}
Let $U \subset M$ be an open set and $c > 0$. Let $(V, \Omega) \in \mathcal{P}_c$ be a weakly stable $h$-surface in $U$ for a function with $\|h\|_{C^1} \leq c$ and $\|V\|(U) \leq m_0$. Let $f : \Sigma \to U$ be the $C^{1,1}$ immersion inducing the varifold $V$ in $U$. Then there is a constant $C = C(U, c, m_0) > 0$ so that
\[ \sup_{p \in \Sigma}\ \min\{1,d_\Sigma(p, f^{-1}(\partial U))\} \ \operatorname{Lip}_p\nu \leq C. \]

\label{thm:min-max}
Suppose $(S^3, g)$ and $h$ satisfy the constraints (\ref{eqn:constraints}) and $\int_{S^3} h\ d\mathcal{H}^3_g \geq 0$. Then there is an open set $\Omega \subset S^3$ satisfying
\begin{itemize}
    \item $\mathcal{A}^h(\Omega) = \omega_1(g, h)$,
    \item $\partial \Omega$ is a disjoint union of smooth embedded spheres with prescribed mean curvature $h$ with respect to $\Omega$.
\end{itemize}

\label{prop:min_max_area_upper_bound}
Suppose $(S^3, g)$ satisfies the hypotheses of \S\ref{sec:min-max_setup}. Suppose $(V, \Omega) \in \mathcal{P}$ satisfies $\|V\|(S^3) - \int_{\Omega} h \ d\mathcal{H}^3 \leq \omega_1(g,h)$. Then
\[ \|V\|(S^3) \leq 4\pi + v c. \]

\label{prop:min_max_area_lower_bound}
Suppose $(S^3, g)$ satisfies the hypotheses of \S\ref{sec:min-max_setup}. If $V$ is a varifold in $(S^3,g)$ with $c$-bounded first variation and $\Theta^2(V,x) \geq 2$ for some $x \in S^3$, then
\[ \|V\|(S^3) \geq \frac{8\pi}{(1+\kappa)^2+c^2/4}. \]

\label{def:weak_replacement}
Let $(V, \Omega) \in \mathcal{P}_c$. A pair $(V', \Omega') \in \mathcal{P}_c$ is a \emph{weak replacement for $(V, \Omega)$ in $U \subset S^3$} if
\begin{itemize}
    \item $V'\llcorner G(M\setminus \overline{U},2) = V \llcorner G(M\setminus \overline{U}, 2)$ and $\Omega \setminus \overline{U} = \Omega' \setminus \overline{U}$,
    \item $|\|V\|(S^3) - \|V'\|(S^3)| \leq c\mathcal{H}^3(U)$,
    \item $\|V'\|(S^3) - \int_{\Omega'}h\ d\mathcal{H}^3 \leq \|V\|(S^3) - \int_{\Omega}h\ d\mathcal{H}^3$,
    \item $(V', \Omega')$ is in the $C^{1,\alpha}_{\text{loc}}$ graphical closure of the set of weakly stable $h$-surfaces in $U$.
\end{itemize}

\label{def:strong_replacement}
Let $(V, \Omega) \in \mathcal{P}_c$. A pair $(V', \Omega') \in \mathcal{P}_c$ is a \emph{replacement for $(V, \Omega)$ in $U \subset S^3$} if
\begin{itemize}
    \item $V'\llcorner G(M\setminus \overline{U},2) = V \llcorner G(M\setminus \overline{U}, 2)$,
    \item $|\|V\|(S^3) - \|V'\|(S^3)| \leq c\mathcal{H}^3(U)$,
    \item $\|V'\|(S^3) - \int_{\Omega'}h\ d\mathcal{H}^3 \leq \|V\|(S^3) - \int_{\Omega}h\ d\mathcal{H}^3$,
    \item $V' \llcorner G(U, 2)$ is an embedded smooth stable surface with prescribed mean curvature $h$ with respect to $\Omega'$.
\end{itemize}

The pair $(V, \Omega) \in \mathcal{P}_c$ has the \emph{good replacement property} if
\begin{enumerate}
    \item there is a positive function $r : U \to \mathbb{R}^+$ such that there is a replacement $(V', \Omega')$ for $(V, \Omega)$ in any annulus centered at $x$ with outer radius at most $r(x)$ for all $x \in U$,
    \item there is a positive function $r' : U \to \mathbb{R}^+$ such that there is a replacement $(V'', \Omega'')$ for the replacement $(V', \Omega')$ from (1) in any annulus centered at $x$ with outer radius at most $r(x)$ and any annulus centered at $y$ with outer radius at most $r'(y)$ for any $y \in U$,
    \item there is a positive function $r'': U \to \mathbb{R}^+$ such that there is a replacement $(V''', \Omega''')$ for the replacement $(V'', \Omega'')$ from (2) in any annulus centered at $z$ with outer radius at most $r''(z)$ for any $z \in U$.
\end{enumerate}

Let $N_i$ ($i=1,2$) be connected embedded two-sided $C^1$ surfaces in a connected open subset $W\subset M$ with $\partial N_i\cap W=\varnothing$. Let $\nu_i$ be the unit normal to $N_i$. We say that $N_2$ \emph{lies on one side of} $N_1$ if $N_1$ divides $W$ into two connected components $W_1\cup W_2=W\setminus N_1$, where $\nu_1$ points into $W_1$ and either:
\begin{itemize}
    \item $N_2\subset\overline{W_1}$, which we write as $N_1\leq N_2$; or
    \item $N_2\subset\overline{W_2}$, which we write as $N_1\geq N_2$.
\end{itemize}

Since the unit normals point in opposite directions, being smooth and minimal follows if we show $N_1 = N_2$.

Suppose for contradiction $N_1 \neq N_2$. Without loss of generality, there is a sequence $x_j \to x$ with $x_j \in N_1 \setminus N_2$. Let $P \subset T_xM$ be the common tangent plane of $N_1$ and $N_2$ at $x$, and let $\nu=\nu_1(x)$ be a unit normal to $P$, so that $\nu_2(x)=-\nu$. Let $r_0 \in (0, 1)$ be sufficiently small so that $\phi_x^{-1}(N_1 \cap B_r^M(x))$ and $\phi_x^{-1}(N_2 \cap B_{r_0}^M(x))$ are $C^{1,\alpha}$ graphs over $B \subset P$, given by $C^{1,\alpha}$ functions $u_1 \geq u_2$ and let $\rho \in (0, r_0/2)$. Let $B_r$ denote $B^{\mathbb{R}^2}_{r}(0)$.

We shall use the same setup as in the proof of Proposition \ref{prop:C1,1_regularity}. We let
\begin{itemize}
    \item $\tilde{g}$ be the rescaled pullback metric $(\phi_x \circ \mu_{\rho})^*g$, so that
\begin{equation*}
    \|\tilde{g} - g_{\text{Euc}}\|_{C^{\infty}(B_2 \times [-1, 1])} \leq \delta(\rho),
\end{equation*}
where $\delta(\rho) \to 0$ as $\rho \to 0$; 
    \item $\tilde{u}_i:B_2\to \mathbb{R}$ be defined by $\tilde{u}_i(x)=\rho^{-1}u_i(\rho x)$ so that 
\begin{equation*}
    \|\tilde{u}_i\|_{C^{1}(B_2)} \leq \delta(\rho);
\end{equation*}
    \item $A(x,z,p)$ be such that with the rescaled metric $\tilde{g}$ on $\mathbb{R}^3$, we have $\mathcal{H}^2(\text{graph }u\vert_{B_r})=\int_{B_r}A(x,u,Du)\ dx$ for all $C^1$ functions $u:B_2\to \mathbb{R}$ and $r\in(0,2)$;
    \item $Q$ be the mean curvature operator for graphs over $B_2$ with respect to $\tilde{g}$.
\end{itemize}

Then $Q(u) \leq 0$ (resp. $\geq 0$) in the weak sense in $B_1$ is equivalent to (in our choice of sign convention)
\[ \int_{B_1} (A_p(x,u,Du) \cdot D\phi + A_z(x,u,Du)\phi) \leq 0 \ (\text{resp. }\geq 0) \]
for all $\phi \in W^{1,2}_0(B_1)$ with $\phi \geq 0$.

By assumption, we have $Q(\tilde{u}_1)\geq 0$ and $Q(\tilde{u}_2)\leq 0$ in the weak sense. If we let $v=\tilde{u}_1-\tilde{u}_2\geq 0$, then $v\in C^{1,\alpha}$ is a non-negative weak supersolution of a linear elliptic equation with continuous coefficients (depending on $\tilde{u}_1$ and $\tilde{u}_2$) as in \cite[Theorem 10.7]{GT}, i.e.
\begin{equation*}
    \int_{B_1} (a^{ij}D_jv + b^iv)D_i\phi - (-b^iD_iv + cv)\phi\geq 0
\end{equation*}
for all non-negative $\phi\in W_0^{1,2}(B_1)$, where $\tilde{u}_t=t\tilde{u}_1+(1-t)\tilde{u}_2$ and
\begin{align*}
    a^{ij} & \coloneqq \int_0^1 A_{p_ip_j}(x, \tilde{u}_t, D\tilde{u}_t)\ dt\\
    b^i & \coloneqq \int_0^1 A_{p_iz}(x, \tilde{u}_t, D\tilde{u}_t)\ dt\\
    c & \coloneqq -\int_0^1 A_{zz}(x, \tilde{u}_t, D\tilde{u}_t)\ dt.
\end{align*}

Since $N_1$ and $N_2$ intersect tangentially at $x$, $v(0)=0$, and $\inf_{B_{1/4}}v=0$. Hence, the weak Harnack inequality for supersolutions \cite[Theorem 8.18]{GT} implies $\|v\|_{L^1(B_{1/2})}=0$. As $v$ is $C^{1,\alpha}$, this means $v\vert_{B_{1/2}}\equiv 0$, contradicting the choice of the sequence $x_j\to x$.
